/**
 *
 * Ripple directive adds ripple effect to the host element.
 *
 * [Live Demo](https://primevue.dev/ripple)
 *
 * @module ripplestyle
 *
 */
import type { BaseStyle, BaseStyleModule } from '@primevue/core/base/style';

export enum RippleClasses {
    /**
     * Class name of the root element
     */
    root = 'p-ink'
}

export interface RippleStyle extends BaseStyle {}

declare const RippleStyle: BaseStyleModule;

export default RippleStyle;
